// Spisak svih dodela (agent i porodice); služi za proveru jedinstvenosti i pregled.
export function iconAssignments() {
  const list = [];
  for (const [agent, cfg] of Object.entries(AGENT_PALETTES)) {
    list.push({ agent, family: null, icon: cfg.icon, color: cfg.color });
    for (const f of cfg.families) list.push({ agent, family: f.match, icon: f.icon, color: f.color });
  }
  return list;
}

export function getAgentConfig(agent) {
  return AGENT_PALETTES[agent] || { name: agent || 'Agent', icon: FALLBACK_ICON, color: '#aaa', accent: '#ccc', families: [] };
}

export function getModelFamily(agent, model = '') {
  const m = String(model || '').toLowerCase();
  if (!m) return null;
  return getAgentConfig(agent).families.find(f => m.includes(f.match)) || null;
}

export function getAgentColor(agent, model = '') {
  return getModelFamily(agent, model)?.color || getAgentConfig(agent).color;
}

export function getAgentIconName(agent, model = '') {
  return getModelFamily(agent, model)?.icon || getAgentConfig(agent).icon;
}

// Dodeljuje ikonicu svakom četu tako da se nijedna ne ponovi.
// Čet prvo dobija ikonicu prema svom ID-ju, a ako je zauzeta, sledeću slobodnu.
// Redosled je po vremenu nastanka, pa stari četovi zadržavaju ikonicu kad nastanu novi.
export function assignChatIcons(chats = []) {
  const pool = CHAT_ICON_POOL;
  const used = new Set();
  const icons = new Map();
  const ordered = [...chats].filter(chat => chat?.id).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0) || String(a.id).localeCompare(String(b.id)));
  for (const chat of ordered) {
    if (icons.has(chat.id)) continue;
    if (used.size >= pool.length) used.clear();
    let index = hashText(chat.id) % pool.length;
    while (used.has(pool[index])) index = (index + 1) % pool.length;
    used.add(pool[index]);
    icons.set(chat.id, pool[index]);
  }
  return icons;
}

function hashText(text) {
  let hash = 2166136261;
  for (const char of String(text)) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619) >>> 0;
  return hash;
}

export function renderAgentIconSvg(iconName, { size = 13, strokeWidth = 1.9, className = 'chat-agent-svg' } = {}) {
  const path = LUCIDE_ICONS[iconName] || LUCIDE_ICONS[FALLBACK_ICON];
  return `<svg class="${className}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
}

const attr = value => String(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');

export function renderChatBadge(chat, { size = 13, strokeWidth = 1.9, icon = '' } = {}) {
  const agent = chat?.settings?.agent || 'codex';
  const model = chat?.settings?.model || '';
  const iconName = LUCIDE_ICONS[icon] ? icon : getAgentIconName(agent, model);
  const svg = renderAgentIconSvg(iconName, { size, strokeWidth });
  const modelAttr = model ? ` data-model="${attr(model)}"` : '';
  return `<span class="chat-agent-badge" data-agent="${attr(agent)}"${modelAttr} data-icon="${iconName}" style="--badge-color:${getAgentColor(agent, model)};">${svg}</span>`;
}
